import {BOARD,LIMITS} from '../../data.js';
import {wishProgress} from './rules.js';
export function validate(s){return s.players.every(p=>p.wish&&(p.wish.points===undefined||([[6],[2,3,4,6],[6],[4]][p.id]).includes(p.wish.points))&&(p.wish.sceneryTarget===undefined||(p.id===1&&[2,'full'].includes(p.wish.sceneryTarget)&&(p.wish.points===4||(p.wish.sceneryTarget==='full'&&p.wish.points===6))))&&(p.wish.sceneryIncludesGifts===undefined||(p.id===1&&[2,'full'].includes(p.wish.sceneryTarget)&&p.wish.sceneryIncludesGifts===true))&&(p.wish.points!==6||p.id!==1||p.wish.sceneryTarget==='full')&&(p.wish.sceneryTarget!=='full'||p.wish.sceneryIncludesGifts===true)&&typeof p.wish.claimed==='boolean'&&['meals','scenery','springs','farms'].every(k=>Array.isArray(p.wish[k])&&(k==='scenery'&&p.id===1?p.wish[k].every(t=>p.wish[k].filter(v=>v===t).length<=(p.wish.sceneryTarget==='full'?LIMITS[t]:(p.wish.sceneryTarget??1))):new Set(p.wish[k]).size===p.wish[k].length))&&p.wish.meals.every(n=>[14,27,41].includes(n))&&p.wish.scenery.every(t=>['paddy','mountain','sea'].includes(t))&&p.wish.springs.every(n=>BOARD[n]?.type==='spring')&&p.wish.farms.every(n=>BOARD[n]?.type==='farm')&&p.wish.claimed===wishProgress(p).complete&&(p.ledger?.wishes||0)===(p.wish.claimed?wishProgress(p).points:0));}
